def calculate_simple_gpa(university, student_id):
    '''
    Calculate the cumulative GPA for a student using their university enrollments.
    Args:
        university: University object with methods for enrollments and courses
        student_id: ID string for the student
    Returns:
        GPA as a float (0.0 - 4.0 scale). Returns 0.0 if no credits attempted.
    '''
    enrollments = university.get_student_enrollments(student_id)
    total_points = 0.0
    total_credits = 0

    for enrollment in enrollments:
        course = university.get_course(enrollment.course_code)
        if course is None:
            continue  # skip if course not found
        grade_points = enrollment.get_grade_points()
        points = grade_points * course.credits
        total_points += points
        total_credits += course.credits

    if total_credits == 0:
